//! The API error type and its mapping to HTTP responses.

use axum::Json;
use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use serde_json::json;

use crate::store::StoreError;

/// An error returned by a handler; rendered as `{"error": "<message>"}`.
#[derive(Debug, thiserror::Error)]
pub enum ApiError {
    #[error("{0}")]
    BadRequest(String),
    #[error("not found")]
    NotFound,
    #[error("method not allowed")]
    MethodNotAllowed,
    #[error("internal error")]
    Internal(#[from] StoreError),
}

impl ApiError {
    pub fn bad_request(message: impl Into<String>) -> Self {
        Self::BadRequest(message.into())
    }

    pub fn status(&self) -> StatusCode {
        match self {
            Self::BadRequest(_) => StatusCode::BAD_REQUEST,
            Self::NotFound => StatusCode::NOT_FOUND,
            Self::MethodNotAllowed => StatusCode::METHOD_NOT_ALLOWED,
            Self::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        if let Self::Internal(err) = &self {
            tracing::error!(error = %err, "request failed");
        }
        (self.status(), Json(json!({ "error": self.to_string() }))).into_response()
    }
}

//! A small notes store over HTTP, backed by SQLite.

pub mod error;
pub mod model;
pub mod routes;
pub mod store;

pub use routes::{AppState, router};
pub use store::Store;

use std::net::{Ipv4Addr, SocketAddr};

use anyhow::{Context, bail};
use notes::{AppState, Store, router};
use tracing_subscriber::EnvFilter;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .with_writer(std::io::stderr)
        .init();

    let mut args = std::env::args().skip(1);
    let (Some(port), None) = (args.next(), args.next()) else {
        bail!("usage: app <port>");
    };
    let port: u16 = port
        .parse()
        .with_context(|| format!("invalid port {port:?}"))?;
    let db_path =
        std::env::var_os("NOTES_DB").context("the NOTES_DB environment variable is not set")?;

    let store = Store::open(&db_path)
        .with_context(|| format!("cannot open database {}", db_path.to_string_lossy()))?;
    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .with_context(|| format!("cannot listen on {addr}"))?;
    tracing::info!(%addr, "listening");

    axum::serve(listener, router(AppState { store }))
        .with_graceful_shutdown(shutdown_signal())
        .await?;
    Ok(())
}

async fn shutdown_signal() {
    if let Err(err) = tokio::signal::ctrl_c().await {
        tracing::error!(error = %err, "cannot listen for the shutdown signal");
        std::future::pending::<()>().await;
    }
}

//! The note model and validation of client input.

use serde::Serialize;
use serde_json::{Map, Value};

use crate::error::ApiError;

pub const TITLE_MAX_CHARS: usize = 200;
pub const TAG_MAX_CHARS: usize = 32;

/// A stored note, as returned by the API.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Note {
    pub id: i64,
    pub title: String,
    pub body: String,
    pub tags: Vec<String>,
}

/// A validated note payload, as accepted by `POST /notes` and `PUT /notes/{id}`.
///
/// `title` is trimmed, `tags` are deduplicated and sorted ascending.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NoteInput {
    pub title: String,
    pub body: String,
    pub tags: Vec<String>,
}

impl NoteInput {
    /// Parses and validates a raw JSON request body.
    pub fn from_json(bytes: &[u8]) -> Result<Self, ApiError> {
        let value: Value = serde_json::from_slice(bytes)
            .map_err(|err| ApiError::bad_request(format!("invalid JSON: {err}")))?;
        match value {
            Value::Object(object) => Self::from_object(&object),
            _ => Err(ApiError::bad_request("request body must be a JSON object")),
        }
    }

    /// Validates a JSON object. Unknown fields are ignored; omitted `body` and `tags` take their defaults.
    pub fn from_object(object: &Map<String, Value>) -> Result<Self, ApiError> {
        let title = match object.get("title") {
            Some(Value::String(title)) => validate_title(title)?,
            Some(_) => return Err(ApiError::bad_request("title must be a string")),
            None => return Err(ApiError::bad_request("title is required")),
        };
        let body = match object.get("body") {
            Some(Value::String(body)) => body.clone(),
            Some(_) => return Err(ApiError::bad_request("body must be a string")),
            None => String::new(),
        };
        let tags = match object.get("tags") {
            Some(Value::Array(items)) => validate_tags(items)?,
            Some(_) => return Err(ApiError::bad_request("tags must be an array of strings")),
            None => Vec::new(),
        };
        Ok(Self { title, body, tags })
    }
}

/// Trims a title and checks its length; returns the trimmed title.
pub fn validate_title(title: &str) -> Result<String, ApiError> {
    let title = title.trim();
    let len = title.chars().count();
    if len == 0 || len > TITLE_MAX_CHARS {
        return Err(ApiError::bad_request(format!(
            "title must be 1-{TITLE_MAX_CHARS} characters"
        )));
    }
    Ok(title.to_owned())
}

/// Whether `tag` is 1–32 characters from `a-z`, `0-9` and `-`.
pub fn is_valid_tag(tag: &str) -> bool {
    (1..=TAG_MAX_CHARS).contains(&tag.len())
        && tag
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
}

/// Validates a list of tags; returns them deduplicated and sorted ascending.
pub fn validate_tags(items: &[Value]) -> Result<Vec<String>, ApiError> {
    let mut tags = items
        .iter()
        .map(|item| match item {
            Value::String(tag) if is_valid_tag(tag) => Ok(tag.clone()),
            _ => Err(ApiError::bad_request(format!(
                "each tag must be 1-{TAG_MAX_CHARS} characters from a-z, 0-9 and -"
            ))),
        })
        .collect::<Result<Vec<_>, _>>()?;
    tags.sort_unstable();
    tags.dedup();
    Ok(tags)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(json: &str) -> Result<NoteInput, ApiError> {
        NoteInput::from_json(json.as_bytes())
    }

    #[test]
    fn applies_defaults() {
        let input = parse(r#"{"title":"first"}"#).unwrap();
        assert_eq!(
            input,
            NoteInput {
                title: "first".into(),
                body: String::new(),
                tags: vec![]
            }
        );
    }

    #[test]
    fn trims_title_and_normalizes_tags() {
        let input = parse(r#"{"title":"  t  ","body":"b","tags":["work","b-2","work"]}"#).unwrap();
        assert_eq!(input.title, "t");
        assert_eq!(input.body, "b");
        assert_eq!(input.tags, ["b-2", "work"]);
    }

    #[test]
    fn title_length_counts_characters() {
        assert!(parse(&format!(r#"{{"title":"{}"}}"#, "é".repeat(200))).is_ok());
        assert!(parse(&format!(r#"{{"title":"{}"}}"#, "a".repeat(201))).is_err());
    }

    #[test]
    fn rejects_invalid_input() {
        for body in [
            r#"{"title": "#,
            "[]",
            "null",
            "{}",
            r#"{"title":"   "}"#,
            r#"{"title":3}"#,
            r#"{"title":"x","body":3}"#,
            r#"{"title":"x","body":null}"#,
            r#"{"title":"x","tags":"a"}"#,
            r#"{"title":"x","tags":["Bad"]}"#,
            r#"{"title":"x","tags":[""]}"#,
            r#"{"title":"x","tags":[1]}"#,
        ] {
            assert!(
                matches!(parse(body), Err(ApiError::BadRequest(_))),
                "accepted {body}"
            );
        }
    }

    #[test]
    fn tag_rules() {
        assert!(is_valid_tag("a-1"));
        assert!(is_valid_tag(&"a".repeat(32)));
        assert!(!is_valid_tag(&"a".repeat(33)));
        assert!(!is_valid_tag(""));
        assert!(!is_valid_tag("a_b"));
        assert!(!is_valid_tag("ü"));
    }
}

//! `PUT` and `DELETE /notes/{id}`.

use axum::body::Bytes;
use axum::extract::State;
use axum::http::StatusCode;
use axum::routing::put;
use axum::{Json, Router};

use super::{AppState, NoteId};
use crate::error::ApiError;
use crate::model::{Note, NoteInput};

pub fn router() -> Router<AppState> {
    Router::new().route("/notes/{id}", put(update_note).delete(delete_note))
}

/// Full replacement: an omitted `body` or `tags` resets it to its default.
async fn update_note(
    State(state): State<AppState>,
    NoteId(id): NoteId,
    body: Bytes,
) -> Result<Json<Note>, ApiError> {
    let input = NoteInput::from_json(&body)?;
    state
        .store
        .update_note(id, input)
        .await?
        .map(Json)
        .ok_or(ApiError::NotFound)
}

async fn delete_note(
    State(state): State<AppState>,
    NoteId(id): NoteId,
) -> Result<StatusCode, ApiError> {
    if state.store.delete_note(id).await? {
        Ok(StatusCode::NO_CONTENT)
    } else {
        Err(ApiError::NotFound)
    }
}

//! `GET /notes` with its query parameters.

use axum::extract::rejection::QueryRejection;
use axum::extract::{Query, State};
use axum::routing::get;
use axum::{Json, Router};
use serde::{Deserialize, Serialize};

use super::AppState;
use crate::error::ApiError;
use crate::model::Note;
use crate::store::list::{ListFilter, MAX_LIMIT};

pub fn router() -> Router<AppState> {
    Router::new().route("/notes", get(list_notes))
}

/// The raw query string of `GET /notes`. Values are kept as strings so that invalid numbers are reported
/// with our own messages; unknown parameters are ignored.
#[derive(Debug, Default, Deserialize)]
struct ListParams {
    tag: Option<String>,
    q: Option<String>,
    after: Option<String>,
    limit: Option<String>,
}

#[derive(Serialize)]
struct NoteList {
    notes: Vec<Note>,
}

async fn list_notes(
    State(state): State<AppState>,
    params: Result<Query<ListParams>, QueryRejection>,
) -> Result<Json<NoteList>, ApiError> {
    let Query(params) = params
        .map_err(|err| ApiError::bad_request(format!("invalid query: {}", err.body_text())))?;
    let filter = ListFilter::try_from(params)?;
    let notes = state.store.list_notes(filter).await?;
    Ok(Json(NoteList { notes }))
}

impl TryFrom<ListParams> for ListFilter {
    type Error = ApiError;

    fn try_from(params: ListParams) -> Result<Self, ApiError> {
        let after = params
            .after
            .map(|raw| {
                parse_integer(&raw).ok_or_else(|| ApiError::bad_request("after must be an integer"))
            })
            .transpose()?;
        let limit = params
            .limit
            .map(|raw| {
                parse_integer(&raw)
                    .and_then(|n| u32::try_from(n).ok())
                    .filter(|n| (1..=MAX_LIMIT).contains(n))
                    .ok_or_else(|| {
                        ApiError::bad_request(format!(
                            "limit must be an integer from 1 to {MAX_LIMIT}"
                        ))
                    })
            })
            .transpose()?
            .unwrap_or(MAX_LIMIT);
        Ok(Self {
            tag: params.tag,
            text: params.q,
            after,
            limit,
        })
    }
}

/// Parses a decimal integer with an optional leading `-`; rejects signs like `+`, spaces and overflow.
fn parse_integer(raw: &str) -> Option<i64> {
    let digits = raw.strip_prefix('-').unwrap_or(raw);
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    raw.parse().ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn params(after: Option<&str>, limit: Option<&str>) -> ListParams {
        ListParams {
            after: after.map(Into::into),
            limit: limit.map(Into::into),
            ..ListParams::default()
        }
    }

    #[test]
    fn integers() {
        assert_eq!(parse_integer("0"), Some(0));
        assert_eq!(parse_integer("42"), Some(42));
        assert_eq!(parse_integer("-3"), Some(-3));
        for raw in [
            "",
            "-",
            "+1",
            " 1",
            "1 ",
            "1.0",
            "1e2",
            "abc",
            "99999999999999999999",
        ] {
            assert_eq!(parse_integer(raw), None, "{raw:?}");
        }
    }

    #[test]
    fn defaults() {
        let filter = ListFilter::try_from(ListParams::default()).unwrap();
        assert_eq!(filter, ListFilter::default());
        assert_eq!(filter.limit, MAX_LIMIT);
    }

    #[test]
    fn valid_paging() {
        let filter = ListFilter::try_from(params(Some("-1"), Some("1"))).unwrap();
        assert_eq!((filter.after, filter.limit), (Some(-1), 1));
        let filter = ListFilter::try_from(params(Some("0"), Some("100"))).unwrap();
        assert_eq!((filter.after, filter.limit), (Some(0), 100));
    }

    #[test]
    fn invalid_paging() {
        for (after, limit) in [
            (None, Some("0")),
            (None, Some("101")),
            (None, Some("-1")),
            (None, Some("")),
            (None, Some("ten")),
            (None, Some("1.5")),
            (None, Some("4294967297")),
            (Some(""), None),
            (Some("x"), None),
            (Some("1.5"), None),
        ] {
            assert!(
                matches!(
                    ListFilter::try_from(params(after, limit)),
                    Err(ApiError::BadRequest(_))
                ),
                "after={after:?} limit={limit:?}"
            );
        }
    }
}

//! HTTP routing. Each submodule owns the endpoints of one feature and exposes a `router()`;
//! [`router`] merges them. Routers may share a path as long as they use different methods
//! (e.g. `GET /notes/{id}` here and `PUT /notes/{id}` in `crud`).

mod crud;
mod list;
mod notes;
mod stats;

use axum::Router;
use axum::extract::{FromRequestParts, Path};
use axum::http::request::Parts;

use crate::error::ApiError;
use crate::store::Store;

/// State shared by all handlers.
#[derive(Clone)]
pub struct AppState {
    pub store: Store,
}

/// The complete application router.
pub fn router(state: AppState) -> Router {
    Router::new()
        .merge(notes::router())
        .merge(crud::router())
        .merge(list::router())
        .merge(stats::router())
        .fallback(async || ApiError::NotFound)
        .method_not_allowed_fallback(async || ApiError::MethodNotAllowed)
        .with_state(state)
}

/// The `{id}` path segment of `/notes/{id}`. Anything but a positive decimal integer is a 404,
/// since no note can have that id.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct NoteId(pub i64);

impl<S: Send + Sync> FromRequestParts<S> for NoteId {
    type Rejection = ApiError;

    async fn from_request_parts(parts: &mut Parts, state: &S) -> Result<Self, Self::Rejection> {
        let Path(raw) = Path::<String>::from_request_parts(parts, state)
            .await
            .map_err(|_| ApiError::NotFound)?;
        parse_note_id(&raw).map(NoteId).ok_or(ApiError::NotFound)
    }
}

fn parse_note_id(raw: &str) -> Option<i64> {
    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    raw.parse().ok().filter(|&id| id > 0)
}

#[cfg(test)]
mod tests {
    use super::parse_note_id;

    #[test]
    fn note_ids() {
        assert_eq!(parse_note_id("1"), Some(1));
        assert_eq!(parse_note_id("42"), Some(42));
        assert_eq!(parse_note_id(&i64::MAX.to_string()), Some(i64::MAX));
        for raw in [
            "",
            "0",
            "-1",
            "+1",
            "abc",
            "1.5",
            " 1",
            "99999999999999999999",
        ] {
            assert_eq!(parse_note_id(raw), None, "{raw:?}");
        }
    }
}

//! `GET /health`, `POST /notes` and `GET /notes/{id}`.

use axum::body::Bytes;
use axum::extract::State;
use axum::http::StatusCode;
use axum::routing::{get, post};
use axum::{Json, Router};

use super::{AppState, NoteId};
use crate::error::ApiError;
use crate::model::{Note, NoteInput};

pub fn router() -> Router<AppState> {
    Router::new()
        .route("/health", get(health))
        .route("/notes", post(create_note))
        .route("/notes/{id}", get(get_note))
}

async fn health() -> &'static str {
    "ok"
}

async fn create_note(
    State(state): State<AppState>,
    body: Bytes,
) -> Result<(StatusCode, Json<Note>), ApiError> {
    let input = NoteInput::from_json(&body)?;
    let note = state.store.create_note(input).await?;
    Ok((StatusCode::CREATED, Json(note)))
}

async fn get_note(
    State(state): State<AppState>,
    NoteId(id): NoteId,
) -> Result<Json<Note>, ApiError> {
    state
        .store
        .get_note(id)
        .await?
        .map(Json)
        .ok_or(ApiError::NotFound)
}

//! `GET /stats` and `GET /tags`.

use std::collections::BTreeMap;

use axum::extract::State;
use axum::routing::get;
use axum::{Json, Router};
use serde::Serialize;

use super::AppState;
use crate::error::ApiError;
use crate::store::stats::TagCount;

pub fn router() -> Router<AppState> {
    Router::new()
        .route("/stats", get(stats))
        .route("/tags", get(tags))
}

#[derive(Serialize)]
struct StatsResponse {
    notes: i64,
    tags: BTreeMap<String, i64>,
}

#[derive(Serialize)]
struct TagsResponse {
    tags: Vec<TagCount>,
}

async fn stats(State(state): State<AppState>) -> Result<Json<StatsResponse>, ApiError> {
    let stats = state.store.stats().await?;
    Ok(Json(StatsResponse {
        notes: stats.notes,
        tags: stats.tags.into_iter().map(|t| (t.tag, t.count)).collect(),
    }))
}

async fn tags(State(state): State<AppState>) -> Result<Json<TagsResponse>, ApiError> {
    let tags = state.store.tag_counts().await?;
    Ok(Json(TagsResponse { tags }))
}

//! Updating and deleting notes (`PUT` and `DELETE /notes/{id}`).

use rusqlite::{TransactionBehavior, params};

use super::notes::insert_tags;
use super::{Result, Store};
use crate::model::{Note, NoteInput};

impl Store {
    /// Replaces the title, body and tags of the note with `id`. Returns the updated note, or
    /// `None` if it does not exist.
    pub async fn update_note(&self, id: i64, input: NoteInput) -> Result<Option<Note>> {
        self.call(move |conn| {
            let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
            let updated = tx.execute(
                "UPDATE notes SET title = ?1, body = ?2 WHERE id = ?3",
                params![input.title, input.body, id],
            )?;
            if updated == 0 {
                return Ok(None);
            }
            tx.execute("DELETE FROM note_tags WHERE note_id = ?1", [id])?;
            insert_tags(&tx, id, &input.tags)?;
            tx.commit()?;
            Ok(Some(Note {
                id,
                title: input.title,
                body: input.body,
                tags: input.tags,
            }))
        })
        .await
    }

    /// Deletes the note with `id` and its tags. Returns whether it existed.
    pub async fn delete_note(&self, id: i64) -> Result<bool> {
        self.call(move |conn| {
            let deleted = conn.execute("DELETE FROM notes WHERE id = ?1", [id])?;
            Ok(deleted > 0)
        })
        .await
    }
}

#[cfg(test)]
mod tests {
    use crate::model::NoteInput;
    use crate::store::test_support::TempStore;

    fn input(title: &str, tags: &[&str]) -> NoteInput {
        NoteInput {
            title: title.into(),
            body: format!("body of {title}"),
            tags: tags.iter().map(|t| t.to_string()).collect(),
        }
    }

    #[tokio::test]
    async fn update_replaces_fields_and_tags() {
        let db = TempStore::new();
        let note = db.store.create_note(input("a", &["x", "y"])).await.unwrap();
        let updated = db
            .store
            .update_note(note.id, input("b", &["y", "z"]))
            .await
            .unwrap()
            .expect("note exists");
        assert_eq!(updated.id, note.id);
        assert_eq!(updated.tags, ["y", "z"]);
        assert_eq!(db.store.get_note(note.id).await.unwrap(), Some(updated));
    }

    #[tokio::test]
    async fn update_missing_note() {
        let db = TempStore::new();
        assert_eq!(
            db.store.update_note(1, input("a", &[])).await.unwrap(),
            None
        );
    }

    #[tokio::test]
    async fn delete_removes_note_and_ids_are_not_reused() {
        let db = TempStore::new();
        let a = db.store.create_note(input("a", &["t"])).await.unwrap();
        assert!(db.store.delete_note(a.id).await.unwrap());
        assert!(!db.store.delete_note(a.id).await.unwrap());
        assert_eq!(db.store.get_note(a.id).await.unwrap(), None);
        let b = db.store.create_note(input("b", &[])).await.unwrap();
        assert_eq!(b.id, a.id + 1);
    }
}

//! Listing notes with filters (`GET /notes`).

use rusqlite::{Row, named_params};

use super::{Result, Store};
use crate::model::Note;

/// The most notes one listing returns, and the default page size.
pub const MAX_LIMIT: u32 = 100;

/// Which notes [`Store::list_notes`] returns. All criteria combine with AND.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ListFilter {
    /// Only notes that have this tag.
    pub tag: Option<String>,
    /// Only notes whose title or body contains this text, ignoring ASCII case.
    pub text: Option<String>,
    /// Only notes with an id greater than this.
    pub after: Option<i64>,
    /// At most this many notes.
    pub limit: u32,
}

impl Default for ListFilter {
    fn default() -> Self {
        Self {
            tag: None,
            text: None,
            after: None,
            limit: MAX_LIMIT,
        }
    }
}

// Tags never contain a comma (see `model::is_valid_tag`), so a comma-joined list splits back losslessly.
// SQLite's `lower` folds ASCII letters only, which matches the "ignoring ASCII case" rule; the needle is
// lowered the same way in Rust.
const LIST_SQL: &str = "
    SELECT n.id, n.title, n.body,
           (SELECT group_concat(t.tag, ',' ORDER BY t.tag) FROM note_tags t WHERE t.note_id = n.id)
    FROM notes n
    WHERE n.id > :after
      AND (:tag IS NULL OR EXISTS (SELECT 1 FROM note_tags t WHERE t.note_id = n.id AND t.tag = :tag))
      AND (:text IS NULL OR instr(lower(n.title), :text) > 0 OR instr(lower(n.body), :text) > 0)
    ORDER BY n.id
    LIMIT :limit
";

impl Store {
    /// Returns the notes matching `filter`, ordered by id ascending.
    pub async fn list_notes(&self, filter: ListFilter) -> Result<Vec<Note>> {
        self.call(move |conn| {
            let text = filter.text.map(|text| text.to_ascii_lowercase());
            let mut stmt = conn.prepare_cached(LIST_SQL)?;
            let notes = stmt
                .query_map(
                    named_params! {
                        ":after": filter.after.unwrap_or(i64::MIN),
                        ":tag": filter.tag,
                        ":text": text,
                        ":limit": filter.limit,
                    },
                    note_with_tags_from_row,
                )?
                .collect::<rusqlite::Result<_>>()?;
            Ok(notes)
        })
        .await
    }
}

